package com.tekwatt.analytics.controller;
import com.tekwatt.analytics.dto.*;import com.tekwatt.analytics.service.AnalyticsService;import jakarta.validation.Valid;import java.time.*;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/analytics") public class AnalyticsController {private final AnalyticsService service;public AnalyticsController(AnalyticsService service){this.service=service;}@PostMapping("/events") @ResponseStatus(HttpStatus.CREATED) Map<String,UUID> record(@Valid @RequestBody AnalyticsEventRequest request){return Map.of("id",service.record(request));}@GetMapping("/overview") AnalyticsOverview overview(@RequestParam UUID tenantId,@RequestParam Instant from,@RequestParam Instant to){return service.overview(tenantId,from,to);}@GetMapping("/daily") List<DailyAnalytics> daily(@RequestParam UUID tenantId,@RequestParam LocalDate from,@RequestParam LocalDate to){return service.daily(tenantId,from,to);}}
